import java.nio.*;import java.nio.file.*;import java.util.*;import java.security.*;
import uk.me.parabola.imgfmt.sys.ImgFS;import uk.me.parabola.imgfmt.mps.*;
public class Inventory{public static void main(String[] args)throws Exception{for(String file:args){try(var fs=ImgFS.openFs(file)){System.out.println("FILE "+file);for(var e:fs.list())if(Set.of("MPS","TYP").contains(e.getExt())){System.out.println(e.getFullName()+" bytes="+e.getSize());try(var ch=fs.open(e.getFullName(),"r")){if(e.getExt().equals("MPS")){var m=new MpsFileReader(ch,1252);for(var p:m.getProducts())System.out.println("PRODUCT family="+p.getFamilyId()+" product="+p.getProductId()+" "+p.getDescription());var maps=m.getMaps();System.out.println("MAPS "+maps.size());for(var map:maps)if(map.getMapNumber()==48320001)System.out.println("COLLIDING TILE "+map.getMapNumber()+" family="+map.getFamilyId()+" "+map.getMapDescription());}else{ByteBuffer b=ByteBuffer.allocate(e.getSize());while(b.hasRemaining())if(ch.read(b)<=0)throw new Exception("truncated");byte[] raw=b.array();Arrays.fill(raw,14,21,(byte)0);System.out.println("TYP normalised SHA256="+HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw)));Files.write(Path.of("/private/tmp/"+Path.of(file).getFileName()+".typ"),b.array());}}}}}}}
